UPDATE environment
SET name = #{name},
    code = #{code},
    remark = #{remark},
    sort_order = #{sortOrder}
WHERE id = #{id}

UPDATE environment
SET is_deleted = 1, deleted_time = #{deletedTime}
WHERE id = #{id}

UPDATE environment
SET is_default = 0
WHERE is_default = 1 AND id != #{excludeId}
